"""Regenerate governance/agent-control-plane/MATRIX.md from YAML registries."""

from __future__ import annotations

from pathlib import Path

import yaml

_REPO = Path(__file__).resolve().parents[2]
_ACP = _REPO / "governance" / "agent-control-plane"
_OUT = _ACP / "MATRIX.md"


def main() -> int:
    roles_doc = yaml.safe_load((_ACP / "role_registry.yaml").read_text(encoding="utf-8"))
    roles = roles_doc.get("roles", {})
    lines = [
        "# Generated by scripts/governance/generate_control_plane_matrix.py — do not edit by hand.\n",
        "| Role | allowed_skills |",
        "|------|----------------|",
    ]
    for name, meta in sorted(roles.items()):
        skills = meta.get("allowed_skills", [])
        joined = ", ".join(skills) if isinstance(skills, list) else ""
        lines.append(f"| {name} | {joined} |")
    lines.append("\nRegenerate: `uv run python scripts/governance/generate_control_plane_matrix.py`\n")
    _OUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"[INFO] wrote {_OUT.relative_to(_REPO)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
